-- =====================================================================
-- Уроки A0.1 (curriculum_a0_v4): імена в діалогах — частіше Даша (Daša, кличний Dašo) · 2026-10-15
-- Згенеровано: python3 scripts/gen_curriculum_a0_v4.py --sync (не редагуйте вручну).
-- Потрібен уже запущений 20261015_curriculum_a0_v4_m01.sql. Оновлює лише репліки й приклади, що відрізняються;
-- стара версія кожної — у content_versions. Безпечно запускати повторно.
-- =====================================================================
do $$
declare
  r record;
  v_old jsonb;
  v_turns int := 0;
  v_examples int := 0;
begin
  for r in select * from jsonb_to_recordset('[{"id": "fdd65063-7819-511c-a88d-b85264fc99d1", "speaker": "Daša", "hr": "Bok, Marko! Kako si?", "ua": "Привіт, Марку! Як справи?"}, {"id": "d6e72123-958d-53f8-9ef4-d922543c2037", "speaker": "Marko", "hr": "Bok, Dašo! Super, hvala. A ti?", "ua": "Привіт, Дашо! Чудово, дякую. А ти?"}, {"id": "0ecf40bf-d3ce-5aa3-9438-8803c5dc5387", "speaker": "Daša", "hr": "Ne baš dobro. Umorna sam.", "ua": "Не дуже добре. Я втомлена."}, {"id": "29f6b491-d3ac-5efc-b7cb-9669f8e482bd", "speaker": "Marko", "hr": "Žao mi je. I ja sam malo umoran.", "ua": "Мені шкода. Я теж трохи втомлений."}, {"id": "a72d6078-7fef-578b-a67e-ea3417f1ce82", "speaker": "Daša", "hr": "Hvala ti. Bok!", "ua": "Дякую тобі. Бувай!"}, {"id": "d244eded-0c5a-5a73-ad01-392be839519f", "speaker": "Gospođa Horvat", "hr": "Dobro došli! Izvolite.", "ua": "Ласкаво просимо! Заходьте."}, {"id": "038f7607-08a2-5bb8-9990-1a40363610a5", "speaker": "Petro", "hr": "Hvala lijepa! Kako ste?", "ua": "Щиро дякую! Як ви?"}, {"id": "a29550b8-f237-5572-9cf6-4b526ded8612", "speaker": "Gospođa Horvat", "hr": "Odlično, hvala. A Vi?", "ua": "Відмінно, дякую. А ви?"}, {"id": "119eff4c-d32b-5161-a449-5ebfd05de3a9", "speaker": "Petro", "hr": "Tako-tako. Imam puno posla.", "ua": "Так собі. У мене багато роботи."}, {"id": "c7c531ce-c8ea-5957-80cd-19a296ff286a", "speaker": "Gospođa Horvat", "hr": "Onda sjednite i odmorite se.", "ua": "Тоді сідайте й відпочиньте."}, {"id": "ab66a3eb-52af-5bc2-999b-bcdd64d905db", "speaker": "Petro", "hr": "Puno hvala!", "ua": "Дуже дякую!"}, {"id": "ae7c403f-7235-572b-b067-cc25290f5123", "speaker": "Gospodin Kovač", "hr": "Dobro jutro, Dašo!", "ua": "Доброго ранку, Дашо!"}, {"id": "2bf3cee5-2a91-532b-b110-5728416288a7", "speaker": "Daša", "hr": "Dobro jutro, gospodine Kovač! Kako ste?", "ua": "Доброго ранку, пане Ковач! Як ви?"}, {"id": "12946429-b1b0-541f-863f-cdf12d1ccd18", "speaker": "Gospodin Kovač", "hr": "Dobro, hvala. Idem na posao.", "ua": "Добре, дякую. Іду на роботу."}, {"id": "bb2ea83b-c8dd-5a28-ba47-94e4be6f008c", "speaker": "Daša", "hr": "I ja. Ugodan dan!", "ua": "Я теж. Гарного дня!"}, {"id": "337435aa-455b-5669-82dd-68c6eace8048", "speaker": "Gospodin Kovač", "hr": "Hvala, i Vama. Doviđenja!", "ua": "Дякую, і вам. До побачення!"}, {"id": "b1b90b56-9b1b-50eb-af45-4b85785cfabf", "speaker": "Maja", "hr": "Ja idem kući. Vidimo se sutra?", "ua": "Я йду додому. Побачимося завтра?"}, {"id": "f1c53d88-4393-5746-828a-d7cd9f985097", "speaker": "Ivan", "hr": "Sutra ne mogu. Čujemo se!", "ua": "Завтра не можу. Зідзвонимося!"}, {"id": "fcec9615-1e08-50bf-9a20-9bac06231200", "speaker": "Maja", "hr": "Dobro. Ugodna večer i ugodan vikend!", "ua": "Добре. Гарного вечора й гарних вихідних!"}, {"id": "2be1977f-8e2e-5436-a228-bc0d72694816", "speaker": "Ivan", "hr": "Hvala, i tebi. Pozdravi mamu!", "ua": "Дякую, і тобі. Передавай привіт мамі!"}, {"id": "832f0601-ab91-5851-98d4-386058d872ce", "speaker": "Maja", "hr": "Hoću. Laku noć!", "ua": "Обов’язково. На добраніч!"}, {"id": "a97fbe3d-9421-5ca0-b8be-7425585b2718", "speaker": "Turist", "hr": "Oprostite, govorite li engleski?", "ua": "Вибачте, ви розмовляєте англійською?"}, {"id": "cb1f77d0-e0d5-52f0-ba7d-20da52cf8001", "speaker": "Prolaznik", "hr": "Malo. Izvolite?", "ua": "Трохи. Слухаю вас?"}, {"id": "4a5fee35-1217-578b-b05c-8ac0d9ea777b", "speaker": "Turist", "hr": "Ne razumijem dobro hrvatski. Možete li govoriti polako?", "ua": "Я погано розумію хорватську. Можете говорити повільно?"}, {"id": "e532581c-abbb-5ace-aa08-b04f26fca6c5", "speaker": "Prolaznik", "hr": "Naravno. Tramvaj broj šest ide u centar.", "ua": "Звісно. Трамвай номер шість їде в центр."}, {"id": "bf919ec5-1182-5b68-b955-075d7c202eef", "speaker": "Turist", "hr": "Oprostite, nisam razumio. Možete li ponoviti?", "ua": "Вибачте, я не зрозумів. Можете повторити?"}, {"id": "49ac812b-9fa4-5ed2-9bcc-b62314fd9f28", "speaker": "Prolaznik", "hr": "Tramvaj broj šest. Šest!", "ua": "Трамвай номер шість. Шість!"}, {"id": "a7f45cca-1635-549c-9fee-2a9b8da9e2b4", "speaker": "Daša", "hr": "Oprostite, što znači »sutra«?", "ua": "Вибачте, що означає «sutra»?"}, {"id": "629d6e00-f4d5-590a-9f29-759d5685de9f", "speaker": "Profesorica", "hr": "Danas je ponedjeljak, a sutra je utorak.", "ua": "Сьогодні понеділок, а завтра вівторок."}, {"id": "30dbf91c-2680-5d3c-bd7f-518e751764f9", "speaker": "Daša", "hr": "Aha, jasno! A kako se kaže »thank you«?", "ua": "А, зрозуміло! А як сказати «thank you»?"}, {"id": "19174428-5e15-5a50-bb9a-a4ffe1a632e8", "speaker": "Profesorica", "hr": "Kaže se: hvala.", "ua": "Кажуть: «hvala»."}, {"id": "e4430435-7d29-5057-9716-ac6f0228fd50", "speaker": "Daša", "hr": "Oprostite, nisam Vas čula. Možete li ponoviti glasnije?", "ua": "Вибачте, я вас не почула. Можете повторити голосніше?"}, {"id": "5d7f8402-2de7-5ad2-818b-49acb350b60d", "speaker": "Profesorica", "hr": "Naravno. Hvala!", "ua": "Звісно. «Hvala»!"}, {"id": "c011b674-b735-5956-8813-300723cdd137", "speaker": "Daša", "hr": "Ispričavam se, kasnim pet minuta.", "ua": "Перепрошую, я запізнююся на п’ять хвилин."}, {"id": "b398bb0b-4a82-5399-8eaa-e0c61dfda60c", "speaker": "Gospođa Horvat", "hr": "Nema problema. Izvolite, sjednite.", "ua": "Нічого страшного. Прошу, сідайте."}, {"id": "02d606d2-d56f-54c1-8077-355d03a47b4c", "speaker": "Daša", "hr": "Hvala. Smijem li otvoriti prozor?", "ua": "Дякую. Можна відчинити вікно?"}, {"id": "b3623791-7c7c-5745-bdd4-c1c9ffcd036f", "speaker": "Gospođa Horvat", "hr": "Slobodno.", "ua": "Прошу, відчиняйте."}, {"id": "f4bb6292-c3a0-5b8b-9015-bb74863ff312", "speaker": "Daša", "hr": "Hvala, jako ste ljubazni.", "ua": "Дякую, ви дуже люб’язні."}, {"id": "037d8118-baee-586e-99ad-5ce1a8640a5a", "speaker": "Gospođa Horvat", "hr": "Molim, nema na čemu.", "ua": "Прошу, нема за що."}, {"id": "64dea03c-8b68-5731-af61-95fc19afb495", "speaker": "Marko", "hr": "Sretan rođendan, Dašo! Čestitam!", "ua": "З днем народження, Дашо! Вітаю!"}, {"id": "c5f61f67-5971-534b-864e-54a4bedb16cf", "speaker": "Daša", "hr": "Hvala, Marko! Izvoli, sok ili vino?", "ua": "Дякую, Марку! Прошу, сік чи вино?"}, {"id": "2d4d95bc-dd70-589e-ad38-0e94ff403051", "speaker": "Marko", "hr": "Vino, molim. Na zdravlje!", "ua": "Вино, будь ласка. Будьмо!"}, {"id": "982346e6-e9d9-5ad7-b5a3-0bebef89a164", "speaker": "Daša", "hr": "Na zdravlje! I sretno na novom poslu!", "ua": "Будьмо! І успіхів на новій роботі!"}, {"id": "cdd2c75f-1483-5119-8776-adabd6221ac1", "speaker": "Marko", "hr": "Hvala, i tebi!", "ua": "Дякую, і тобі!"}]'::jsonb) as x(id uuid, speaker text, hr text, ua text) loop
    select to_jsonb(t) into v_old from public.conversation_turns t
     where t.id = r.id and (t.speaker_name, t.hr_text, t.ua_translation) is distinct from (r.speaker, r.hr, r.ua);
    if v_old is null then continue; end if;
    insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
    values ('conversation_turn', r.id, coalesce((select max(version) from public.content_versions where entity_type = 'conversation_turn' and entity_id = r.id), 0) + 1,
            v_old, 'curriculum_a0_v4: імена в діалогах (Даша) — стара версія');
    update public.conversation_turns set speaker_name = r.speaker, hr_text = r.hr, ua_translation = r.ua where id = r.id;
    v_turns := v_turns + 1;
  end loop;
  for r in select * from jsonb_to_recordset('[{"lemma": "zdravo", "example": "Zdravo, kako si?"}, {"lemma": "puno hvala", "example": "Puno hvala na pomoći!"}, {"lemma": "ne baš dobro", "example": "Kako si? — Ne baš dobro, malo sam bolestan."}, {"lemma": "tako-tako", "example": "Kako ide posao? — Tako-tako."}, {"lemma": "a ti", "example": "Dobro sam, hvala. A ti?"}, {"lemma": "a vi", "example": "Dobro, hvala. A Vi?"}, {"lemma": "i ja", "example": "Umoran sam. — I ja."}, {"lemma": "ugodan vikend", "example": "Doviđenja i ugodan vikend!"}, {"lemma": "vidimo se kasnije", "example": "Sad moram ići, vidimo se kasnije!"}, {"lemma": "do skorog viđenja", "example": "Hvala na svemu i do skorog viđenja!"}, {"lemma": "pozdrav", "example": "Pozdrav, Ivane! Kako si?"}, {"lemma": "lijep pozdrav", "example": "Vidimo se u ponedjeljak. Lijep pozdrav, Daša"}, {"lemma": "oprosti", "example": "Oprosti, nisam te čuo."}, {"lemma": "nisam razumio", "example": "Oprostite, nisam razumio. Možete li ponoviti?"}, {"lemma": "nisam te čuo", "example": "Oprosti, nisam te čuo. Što si rekla?"}, {"lemma": "sporije", "example": "Možete li govoriti sporije?"}, {"lemma": "glasnije", "example": "Ne čujem Vas. Govorite glasnije, molim."}, {"lemma": "što znači", "example": "Što znači ova riječ?"}, {"lemma": "možete li napisati", "example": "Možete li napisati adresu?"}, {"lemma": "jasno", "example": "Aha, sad mi je jasno."}, {"lemma": "hvala na pomoći", "example": "Hvala na pomoći, jako ste ljubazni."}, {"lemma": "i vama", "example": "Ugodan dan! — Hvala, i Vama."}, {"lemma": "slobodno", "example": "Smijem li sjesti? — Slobodno."}, {"lemma": "smijem li", "example": "Smijem li otvoriti prozor?"}, {"lemma": "svakako", "example": "Doći ćeš na rođendan? — Svakako!"}, {"lemma": "na zdravlje", "example": "Podignimo čaše. Na zdravlje!"}, {"lemma": "pristojan", "example": "Naš susjed je uvijek pristojan."}]'::jsonb) as x(lemma text, example text) loop
    select to_jsonb(l) into v_old from public.lexemes l
     where lower(l.lemma) = lower(r.lemma) and l.source = 'claude_curriculum_a0_v4' and l.examples is distinct from jsonb_build_array(r.example);
    if v_old is null then continue; end if;
    insert into public.content_versions (entity_type, entity_id, version, payload, change_reason)
    values ('lexeme', (v_old->>'id')::uuid, coalesce((select max(version) from public.content_versions where entity_type = 'lexeme' and entity_id = (v_old->>'id')::uuid), 0) + 1,
            v_old, 'curriculum_a0_v4: імена в діалогах (Даша) — стара версія');
    update public.lexemes set examples = jsonb_build_array(r.example) where id = (v_old->>'id')::uuid;
    v_examples := v_examples + 1;
  end loop;
  raise notice 'Готово: оновлено реплік — %, прикладів — %', v_turns, v_examples;
end $$;
